#include <algorithm>
#include <array>
#include <cstdint>
#include <functional>
#include <iostream>
#include <numeric>
#include <stdexcept>
#include <utility>
#include <vector>
using namespace std;using ll=long long;using Graph=vector<uint64_t>;using Label=pair<int,int>;
void need(bool t,const char*s){if(!t)throw runtime_error(s);}
ll power(ll b,int n){ll a=1;while(n--)a*=b;return a;}
struct G{Graph a;vector<Label>labels;array<vector<int>,7>blocks;};
G make(int t,int j,int m){int q[7]={14,4,32,118,103,67,7};int size[7]={1,t,1,2,j,2,m};G g;for(int b=0;b<7;b++)for(int k=0;k<size[b];k++){g.blocks[b].push_back(g.labels.size());g.labels.push_back({b,k});}g.a.resize(g.labels.size());for(int x=0;x<(int)g.a.size();x++)for(int y=0;y<(int)g.a.size();y++)if(x!=y){auto [b,k]=g.labels[x];auto [c,l]=g.labels[y];if(b==c?k<l:((q[b]>>c)&1))g.a[x]|=1ULL<<y;}return g;}
array<ll,3> literal(const Graph&a,int root){int n=a.size(),N=1<<n;vector<ll>h(N),s(N);h[0]=1;ll e=0;function<void(int,int,bool)>dfs=[&](int S,int v,bool marked){h[S]++;if(marked)s[S]++;if(S==N-1&&v==root)e++;for(int bits=a[v]&~S;bits;bits&=bits-1){int z=bits&-bits;dfs(S|z,__builtin_ctz((unsigned)z),marked);}};for(int i=0;i<n;i++)dfs(1<<i,i,i==root);ll R=0;for(int S=1;S<N;S++)R+=s[S]*h[(N-1)^S];return{h[N-1],e,R};}
bool cover(const Graph&a,int v,vector<int>c){for(int x=0;x<(int)a.size();x++)if(a[v]>>x&1)for(int y=0;y<(int)a.size();y++)if((a[y]>>v&1)&&(a[x]>>y&1)&&find(c.begin(),c.end(),x)==c.end()&&find(c.begin(),c.end(),y)==c.end())return false;return true;}
Graph born(Graph a,vector<int>ports,bool left){int n=a.size();a.push_back(0);for(int i=0;i<n;i++){bool selected=find(ports.begin(),ports.end(),i)!=ports.end();if(left?!selected:selected)a[n]|=1ULL<<i;else a[i]|=1ULL<<n;}return a;}
void move_test(int t,int j,int m,bool right){G old=make(t,j,m),target=make(t+(right?1:-1),j+(right?-1:1),m);int removed=right?old.blocks[4].front():old.blocks[1].back();vector<int>keep;for(int i=0;i<(int)old.a.size();i++)if(i!=removed)keep.push_back(i);Graph a(keep.size());vector<Label>names;for(int x=0;x<(int)keep.size();x++){for(int y=0;y<(int)keep.size();y++)if(old.a[keep[x]]>>keep[y]&1)a[x]|=1ULL<<y;Label label=old.labels[keep[x]];if(label.first==4)label.second+=right?-1:1;names.push_back(label);}auto index=[&](int v){auto p=find(keep.begin(),keep.end(),v);need(p!=keep.end(),"exposed port deleted");return int(p-keep.begin());};vector<int>oldports{old.blocks[6].back(),old.blocks[2][0],old.blocks[3][0],old.blocks[3][1]};vector<int>ports;for(int v:oldports)ports.push_back(index(v));a=born(a,right?vector<int>{ports[1]}:vector<int>{ports[2],ports[3]},!right);names.push_back(right?Label{1,t}:Label{4,0});vector<int>f;for(auto label:names){auto p=find(target.labels.begin(),target.labels.end(),label);need(p!=target.labels.end(),"target label");f.push_back(p-target.labels.begin());}for(int x=0;x<(int)a.size();x++)for(int y=0;y<(int)a.size();y++)need(((a[x]>>y)&1)==((target.a[f[x]]>>f[y])&1),"literal delete birth identity");vector<int>newports{target.blocks[6].back(),target.blocks[2][0],target.blocks[3][0],target.blocks[3][1]};for(int k=0;k<4;k++)need(f[ports[k]]==newports[k],"retained port label");}
int main(){int graphcontrols=0,maps=0,countcontrols=0,responsecontrols=0;vector<array<ll,6>>records;for(int t=1;t<=7;t++)for(int j=1;j<=7;j++)for(int m=1;m<=6;m++){auto g=make(t,j,m);int n=g.a.size();vector<int>cycle;for(int b:vector<int>{0,3,4,1,2,5,6})cycle.insert(cycle.end(),g.blocks[b].begin(),g.blocks[b].end());auto sorted=cycle;sort(sorted.begin(),sorted.end());for(int i=0;i<n;i++){need(sorted[i]==i,"Hamilton cycle vertices");need(g.a[cycle[i]]>>cycle[(i+1)%n]&1,"Hamilton cycle edges");for(int k=i+1;k<n;k++)need(((g.a[i]>>k)&1)+((g.a[k]>>i)&1)==1,"tournament quotient");}for(int u:g.blocks[1])need(cover(g.a,u,{g.blocks[2][0]}),"U crossing cover");for(int z:g.blocks[4])need(cover(g.a,z,{g.blocks[0][0]}),"Z crossing cover");for(int r:g.blocks[6])need(cover(g.a,r,{g.blocks[0][0],g.blocks[2][0]}),"R crossing cover");if(j>=2){move_test(t,j,m,true);maps++;}if(t>=2){move_test(t,j,m,false);maps++;}graphcontrols++;
 if(n<=14){auto h=literal(g.a,n-1);need(h[0]==30*power(2,t+j)*power(3,m)+1,"literal count tensor");records.push_back({t,j,m,h[0],h[1],h[2]});countcontrols++;}
 if(m==1){Graph w=born(g.a,{n-1},false);for(int u:g.blocks[1])need(cover(w,u,{g.blocks[2][0],n}),"augmented U cover");for(int z:g.blocks[4])need(cover(w,z,{g.blocks[0][0]}),"augmented Z cover");if(n+1<=14){auto h=literal(g.a,n-1);auto z=literal(w,n);need(h[1]==30*power(2,j)-3,"literal endpoint tensor");need(h[2]==(90*power(3,t)+24*power(2,t)-27)*power(2,j)+6*power(3,t)+1,"literal reserved-cover tensor");need(z[0]==h[0]-h[1]+h[2],"augmented root identity");responsecontrols++;}}}
 for(int j=2;j<=40;j++){ll u=power(2,j),h=180*u+1,ea=30*u-3,Ra=291*u+19,eb=15*u-3,Rb=879*(u/2)+55;ll A=h-ea+Ra,B=h-eb+Rb;need(A==441*u+23&&B==1209*(u/2)+59,"children formulas");need(A<B&&B<h+2*Ra&&B<3*Ra&&2*Rb>=B,"all gadget inequality bounds");}
 cout<<"{\n  \"status\":\"PASS\",\n  \"quotient_and_cover_graphs\":"<<graphcontrols<<",\n  \"literal_delete_birth_maps\":"<<maps<<",\n  \"literal_path_count_graphs\":"<<countcontrols<<",\n  \"literal_response_and_augmented_graphs\":"<<responsecontrols<<",\n  \"physical_profiles\":[\n";for(int i=0;i<(int)records.size();i++){auto z=records[i];cout<<(i?",\n":"")<<"    [";for(int k=0;k<6;k++)cout<<(k?",":"")<<z[k];cout<<"]";}cout<<"\n  ]\n}\n";}
